import{F as e,v as t,y as n}from"./vue-BIc-26Rf.js";import{t as r}from"./app-Do_Yjdds.js";var i=JSON.parse(`{"path":"/main/sf-1/output/novel/chapters/245.html","title":" | 洄门拾遗","lang":"zh-CN","frontmatter":{"description":"口上的秤台空着。霜从台面退到门槛外，退了两指宽。 一三三五头班。 工程方的值工先到，拎一只铁匣，匣盖上贴着封条。封条号他念了一遍，抬眼让祁昭看清，才启封。 砂鸣把匣里的东西一件一件摆到托板上：纸卷、干燥剂、两根转接线。 「件号。」值工说。 砂鸣念一件，他核一件，核完在工单上画一道。念到转接线，砂鸣停住。 「这一件的号，牌上没有。」 「牌上写的是这批的号...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://ajtn123.github.io/novels/main/sf-1/output/novel/chapters/245.html"}],["meta",{"property":"og:site_name","content":"小说文库"}],["meta",{"property":"og:description","content":"口上的秤台空着。霜从台面退到门槛外，退了两指宽。 一三三五头班。 工程方的值工先到，拎一只铁匣，匣盖上贴着封条。封条号他念了一遍，抬眼让祁昭看清，才启封。 砂鸣把匣里的东西一件一件摆到托板上：纸卷、干燥剂、两根转接线。 「件号。」值工说。 砂鸣念一件，他核一件，核完在工单上画一道。念到转接线，砂鸣停住。 「这一件的号，牌上没有。」 「牌上写的是这批的号..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"readingTime":{"minutes":7.4,"words":2219},"git":{"createdTime":1794191409000},"autoDesc":true,"filePathRelative":"main/sf-1/output/novel/chapters/245.md","headers":[]}`),a={name:`245.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<p>口上的秤台空着。霜从台面退到门槛外，退了两指宽。</p><p>一三三五头班。</p><p>工程方的值工先到，拎一只铁匣，匣盖上贴着封条。封条号他念了一遍，抬眼让祁昭看清，才启封。</p><p>砂鸣把匣里的东西一件一件摆到托板上：纸卷、干燥剂、两根转接线。</p><p>「件号。」值工说。</p><p>砂鸣念一件，他核一件，核完在工单上画一道。念到转接线，砂鸣停住。</p><p>「这一件的号，牌上没有。」</p><p>「牌上写的是这批的号。这一件另编过。」值工把工单转过来给他看，「我核的是插上去这两件和这根线。匣里那一堆我没开，我不签。」</p><p>「行。」砂鸣说。</p><p>接电只走白线外那一小段。值工把两根线各扣进柜侧的一个转出口，扣好，抬手让缇珂看。缇珂点头，他落名，笔插回胸前。</p><p>「电门我管的只有这一道。」他说，「壳侧那一支，不归我这行签。」</p><p>「这几天不过船，那一支照原样开着。」陆徊说。</p><p>「那是供能班的话。」值工把铁匣往里推了半尺，「我只管电门。」</p><p>砂鸣把干燥剂摆正，布在匣口擦了一圈。「我留下看匣。蹲久了不行，我坐托板上。」</p><p>「你留下。」</p><p>「件号三件，两件在牌上，一件另编。」砂鸣伸出两根手指，又添半根，自己看了一眼，「算两件半。就这个数，别往别处写。」</p><p>口上不领牌。缇珂带他们走口外那条平道，说访客线记名就行。</p><p>卸料臂收在架子上，折成两段。风横着走，把袖口的绳头往一边拨。秤台边摞着空筐，筐底一层白霜，化了又冻。</p><p>值守在窗后，头发剃得很短，鬓角一层白。窗上开一道缝，缝下是木托盘。他把簿推到窗边，两根指头压住页角。</p><p>「四栏。排、到、过、离。」</p><p>「念一三三五。」陆徊说。</p><p>「排：不排。到、过、离：三横线。」他念完，抬眼，「横线我用尺画。手画的线，回头有人说斜了。」</p><p>「空着的栏，和画了横线的，差在哪儿。」</p><p>「空是数没到。横线是不排。」值守把尺挪到下一行，「空着的我不敢当零，画了横线的我敢。」</p><p>「一三三四。」</p><p>「头班过一条，卸料，一班。第二、第三、末，都不排。」</p><p>「一三三三。」</p><p>「第二班一条，第三班一条，都是卸料。」</p><p>祁昭一栏一栏抄。「这一班还有别的从口上过。」</p><p>「工程车走旁门。旁门那本在工程方手上。」值守说，「检修艇停在七桩外，一三三九早班返，也不走我这本。」</p><p>「那你这本只证运补船。」祁昭说。</p><p>「我这本只到我这一栏。」值守说，「出了口，谁走哪儿我不管。」</p><p>陆徊问：「这个口，连空过几个班。」</p><p>「三年没有连空三个班。」值守把簿合了一半，又打开，「上一回是六年前检修。我在这个口十一年，空着，我反倒不认得。」</p><p>祁昭落：「一三三五，本口运补船不排；值守口述，簿未出窗。」</p><p>第三班，三号柜前。</p><p>抹字牌上三行，第三行是刚写的。笔头压得重，一位小数。</p><p>四十七点一。四十七点一。四十七点一。</p><p>「头班和第二班是别班的手。」缇珂说。</p><p>「第三行是你。」</p><p>「我这一班。」她把布在手上绕了两圈，「签我名的行，我能站在这儿说。别班那两行，我只报手迹。」</p><p>「派工口拿这几行做什么。」陆徊问。</p><p>「算余量，也拿它当本口这几天的参照。他们按船算：来一条，掉一格；不来，回一格。」</p><p>「一格是多少。」祁昭问。</p><p>「零点一。」缇珂说，「撤一条船掉一格。平常换班，也掉一格。」</p><p>「一三三一到一三三四，六行掉了两格。」陆徊说，「那六行都有船。」</p><p>「有船。」</p><p>「今天三行一个数。」</p><p>「一个数。」缇珂说。</p><p>祁昭的记录仪抬起来，又放下。「按他们那本账，今天一条船都没有，这几行该回上去。没回。」</p><p>「我这一块牌上没回。」</p><p>「你这块牌写的是什么。」</p><p>「写流。」缇珂说，「谁给的，牌上不认。」</p><p>「销。」陆徊说。</p><p>「销在座上。我这一班看过，没弹。」她顿了一下，「没弹就是没断过。用了多少，座上没有数。」</p><p>「这一次你不用听。」祁昭说。</p><p>「听来的证不了这一格。」陆徊说。</p><p>料车是第三班后头到的。车斗里是检修要用的夹具，码得整整齐齐。车手下车，先从胸袋里抽一张单。</p><p>「闻棠那一班，一班两格，她签了。」</p><p>「谁叫谁付。」陆徊说。</p><p>「她写的就是这一句。」</p><p>祁昭接过去看。「这一班她量了柜面，没量别的。」</p><p>「单上没写量什么。」车手说。</p><p>陆徊在单上落一行：转赫仑联合本班，谈九报批。写完递回去。「这个通道，你递得到吗。」</p><p>「单跟着车走。递到收文口，收文口盖日子，盖了才算递到。」车手把单折起，塞回胸袋。</p><p>「还有一个信袋。」他从车斗底下的铁箱里抽出一只纸袋，「中继转的。收件栏写你的名。」</p><p>纸袋封口上是骸环号柜的印，印下三段转递号。陆徊在袋角按了手，车手才撕封。</p><p>里面一张回执，一页，五栏加一段附记。</p><p>祁昭念：「缴项：续号。格数：八格。汇转：半格，当日确认。起止：一三三六至一三六五。核验：骸环，须本人到。」</p><p>「收讫日。」</p><p>「一三三四。」</p><p>「送联那一栏。」</p><p>祁昭把纸转过来。「写的是你的名。」</p><p>附记两行：船仍在骸环挂泊，弯肋禁载与漏机照旧；泊费按旬另缴，不入此笔。</p><p>背面有手写的一行，笔头很重：「号是我的，钱是我的。十八那笔不抵这个。」</p><p>陆徊在终端上把数过了一遍。三班九格，八格进号柜，半格走汇转，剩半格。</p><p>「抄进我这一页。」祁昭说。</p><p>「抄。」</p><p>她抄完，底下落出处：「号柜回执，中继三段转递，抄件不代原件；原件在本人手上。」</p><p>陆徊用右手把回执折起来，折到第二道纸滑了一下，祁昭伸手压住。终端夹层那块玻璃板后头原来压着两张，卸料单的抄件，阿栗第九期的联。他把新的塞在最外头。</p><p>「有捎话的位没有。」他问车手。</p><p>「捎话不收费。捎东西按件。」</p><p>「一句话。」</p><p>车手等了等。「你说。」</p><p>「号续了，我看见了。别的没有。」</p><p>车手点头，把铁箱扣上。「话我带。带不到不赔。」</p><p>末班收电，值工把两根线从转出口退出来，扣回匣里，在工单上签了收电那一格。砂鸣把纸卷从匣口拉出一截，撕口正落在收电那一格上。</p><p>「走了四个班。」他说，「头一段到末一段，一条线。我中间在托板上坐了两回，纸没断。」</p><p>「有台阶没有。」</p><p>「班与班之间有齿孔。齿孔对下来，一个台阶都没有。」砂鸣把纸摊在托板上，用指头压住两头，「匣里那两路是一条线画两遍，我知道。可它比牌上细：牌上一班一行，这上头一格一格。」</p><p>祁昭蹲下去看。「钟点在齿孔上。」</p><p>「齿孔是匣子自己咬的。我把纸对准了齿孔，人还是对不准。」砂鸣把撕口那一端递给他。</p><p>口边的交接桌上，值守正把簿摊开，画最后一条横线。尺压得很死，线走得很直。</p><p>陆徊把纸带放在桌上，放在「不排」那一行旁边。</p><p>值守抬眼。「这上头是数。」</p><p>「是。」</p><p>「我这一本只到过口。」他把尺收进袖里，把簿合上，掌心在封面上按了一下，「数在纸上，纸不在我这儿。」</p><p>陆徊把纸带往那一行推了推，撕口正好落在「不排」的右边。</p><p>「这一格是空的。」他说，「这一路，一格没回。」</p><p>缇珂把灯举高，照着桌上那两样东西。她的鳃罩沿上又结了一圈盐霜。</p><p>「明天还是不过船。」她说。</p><p>「到检修那天。」</p><p>「到检修那天。」</p><p>「远点那个名额还在。」陆徊说。</p><p>「在。要座。」</p><p>「要座。」</p><p>她把灯往通道那头照，水线又往前爬了一指。「你名下那一个座，一三三九早班。第二个，你没申请。」</p><p>「明天申请。」</p><p>「申请要名，还要到岗工时。」缇珂把灯换到左手，右手在罩沿上刮了一下盐霜，「工时谁付，也得有人落名。」</p><p>陆徊把纸带卷起来，卷到撕口那儿停住，塞进玻璃板后头，压在回执外头。</p><p>簿已经合了，那一页留在里面。纸带的撕口朝着外头。</p>`,111)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};